Import ListNotations.
Open Scope bv_scope.
Unset Lia Cache. Unset Nia Cache. Unset Nra Cache.
Ltac Zify.zify_convert_to_euclidean_division_equations_flag ::= constr:(false).

(* [comment removed for export] *)
Definition MFR (m : word -> option byte) (s : Z) (ret : word) (regs : bvmap 5 word) : word -> option byte :=
  wbytes (wbytes m (Z_to_bv 64 (s - 8)) (word_to_le_bytes 8 ret)) (Z_to_bv 64 (s - 16)) (word_to_le_bytes 8 (getr regs 8)).

Ltac fz Hz := cbn [fp_csr]; repeat apply fpv_frm_acc; exact Hz.
Ltac fpn := cbn [fp_regs fp_csr].
(* [comment removed for export] *)
Ltac fmvwx F D := chain_step; [ reflexivity | eapply fp_step_fmv_w_x; [exact F | reflexivity | exact D] | step_simpl ]; fpn.
Ltac fcmp F D := chain_step; [ reflexivity | eapply fpv_step_fcmp; [exact F | reflexivity | exact D] | step_simpl ]; fpn.
Ltac fsgn F D := chain_step; [ reflexivity | eapply fpv_step_fsgnj; [exact F | reflexivity | exact D] | step_simpl ]; fpn.
Ltac fari F D Hz := chain_step; [ reflexivity | eapply fpv_step_fari; [exact F | reflexivity | exact D | fz Hz | reflexivity] | step_simpl ]; fpn.
(* [comment removed for export] *)
Ltac bsplit :=
  lazymatch goal with
  | |- context [if fst (fpv_cmp ?o ?f ?a ?b) then Z_to_bv 64 1 else Z_to_bv 64 0] => destruct (fst (fpv_cmp o f a b))
  end.

Section Segs.
Variable rom : word -> option byte.
#[local] Notation "'u'" := bv_unsigned (only parsing).
(* [comment removed for export] *)
#[local] Instance mod_fxd : FPState | 100 := mkFP bvmap_empty (Z_to_bv 32 0).
Ltac sok_in SOK :=
  store_ok_peel;
  first [ exact SOK
        | eapply store_ok_sub; [ | exact SOK | | ]; rewrite ?length_N_to_le_bytes, ?u_Z2bv by lia; cbn [Z.of_nat Pos.of_succ_nat Pos.succ]; lia ].

(* [comment removed for export] *)
Lemma mod_A : forall fr cs regs m (s po : Z) (ret : word),
  (16 <= s)%Z -> (s < 2 ^ 64)%Z -> (1 <= po)%Z -> (po + 4 <= 2 ^ 64)%Z -> frm_zero cs ->
  store_ok SEGS m (Z_to_bv 64 (s - 16)) 16 = true -> store_ok SEGS m (Z_to_bv 64 po) 4 = true ->
  getr regs 2 = Z_to_bv 64 s -> getr regs 1 = ret -> getr regs 10 = Z_to_bv 64 po ->
  reach SEGS (@mkst (mkFP fr cs) regs (0x9b99c : word) m rom)
    (fun fin => exists fr' cs' regs' (pc' : word),
       fin = @mkst (mkFP fr' cs') regs' pc' (wr4 (MFR m s ret regs) po 0) rom /\ frm_zero cs' /\
       (pc' = (0x9b9c4 : word) \/ pc' = (0x9ba40 : word)) /\
       getr regs' 2 = Z_to_bv 64 (s - 16) /\ getr regs' 10 = Z_to_bv 64 po /\
       regs_agree (fun r => In r [2; 12]%list) regs regs').
Proof.
