(* [comment removed for export] *)
Lemma mod_N : forall (fx : FPState) regs m,
  rdn SEGS m (Z_to_bv 64 0x1125c8) 8 = Some (Z_to_le_bytes 8 0x1137b8) -> rdn SEGS m (Z_to_bv 64 0x1137b8) 4 = Some (Z_to_le_bytes 4 3) ->
  exists regs',
    msteps SEGS (@mkst fx regs (0x9b9c4 : word) m rom) (@mkst fx regs' (0x63080 : word) m rom)
    /\ getr regs' 1 = Z_to_bv 64 0x9b9ec /\ getr regs' 10 = Z_to_bv 64 0x1b5a1 /\ getr regs' 11 = Z_to_bv 64 0x19cb2
    /\ regs_agree (fun r => In r [1; 10; 11]%list) regs regs'.
Proof.
